public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) return 0;
    int rows = grid.length;
    int totalCells = 0;
    int[] rowLengths = new int[rows];
    for (int r = 0; r < rows; r++) {
        if (grid[r] == null) {
            rowLengths[r] = 0;
        } else {
            rowLengths[r] = grid[r].length;
            totalCells += rowLengths[r];
        }
    }
    boolean[][] visited = new boolean[rows][];
    for (int r = 0; r < rows; r++) {
        visited[r] = new boolean[rowLengths[r]];
    }
    int[] stackR = new int[totalCells];
    int[] stackC = new int[totalCells];
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};
    int count = 0;
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < rowLengths[r]; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                count++;
                int top = 0;
                stackR[top] = r;
                stackC[top] = c;
                visited[r][c] = true;
                top++;
                while (top > 0) {
                    top--;
                    int cr = stackR[top];
                    int cc = stackC[top];
                    for (int d = 0; d < 8; d++) {
                        int nr = cr + dr[d];
                        int nc = cc + dc[d];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < rowLengths[nr]
                                && grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stackR[top] = nr;
                            stackC[top] = nc;
                            top++;
                        }
                    }
                }
            }
        }
    }
    return count;
}

