public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    java.util.HashSet<Integer> set = new java.util.HashSet<>();
    for (int num : numbers) {
        set.add(num);
    }
    int count = 0;
    for (int num : numbers) {
        if (num % 2 == 0 && set.contains(num / 2)) {
            count++;
        }
    }
    return count;
}

