public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate n and coordinates
    if (n <= 0 || start == null || end == null || start.length != n || end.length != n) {
        return "cannot be travelled";
    }
    // Helper to convert coordinate array to string key
    java.util.function.Function<int[], String> keyOf = (int[] coords) -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coords.length; i++) {
            sb.append(coords[i]);
            if (i < coords.length - 1) sb.append(',');
        }
        return sb.toString();
    };
    String startKey = keyOf.apply(start);
    String endKey = keyOf.apply(end);
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }
    // Build adjacency list
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    // Ensure all nodes appear in graph
    graph.put(startKey, new java.util.ArrayList<>());
    graph.put(endKey, new java.util.ArrayList<>());
    if (paths != null) {
        for (int[] path : paths) {
            // Each path should contain 2*n integers: start coords then end coords
            if (path == null || path.length != 2 * n) {
                continue; // skip malformed path
            }
            int[] a = new int[n];
            int[] b = new int[n];
            System.arraycopy(path, 0, a, 0, n);
            System.arraycopy(path, n, b, 0, n);
            String aKey = keyOf.apply(a);
            String bKey = keyOf.apply(b);
            graph.computeIfAbsent(aKey, k -> new java.util.ArrayList<>()).add(bKey);
            graph.computeIfAbsent(bKey, k -> new java.util.ArrayList<>()).add(aKey); // assume undirected
        }
    }
    // BFS to find connectivity
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = graph.get(current);
        if (neighbors == null) continue;
        for (String neigh : neighbors) {
            if (!visited.contains(neigh)) {
                if (neigh.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(neigh);
                queue.add(neigh);
            }
        }
    }
    return "cannot be travelled";
}

