public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        return "Invalid date format";
    }
    try {
        java.time.format.DateTimeFormatter formatter = java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy");
        java.time.LocalDate localDate = java.time.LocalDate.parse(date.trim(), formatter);
        String monthName = localDate.getMonth().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        String weekdayName = localDate.getDayOfWeek().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        int day = localDate.getDayOfMonth();
        int year = localDate.getYear();
        return monthName + " " + day + ", " + year + " is a " + weekdayName;
    } catch (Exception e) {
        return "Invalid date format";
    }
}

