public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    int[] remCount = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        remCount[r]++;
    }
    // Check remainder 0
    if (remCount[0] % 2 != 0) {
        return false;
    }
    // If k is even, check remainder k/2
    if (k % 2 == 0) {
        int mid = k / 2;
        if (remCount[mid] % 2 != 0) {
            return false;
        }
    }
    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // already handled when k even
            continue;
        }
        if (remCount[r] != remCount[k - r]) {
            return false;
        }
    }
    return true;
}

