public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    int total = 1 << k;  // total number of binary strings of length k
    java.util.HashSet<Integer> seen = new java.util.HashSet<>(total);
    int mask = total - 1; // mask to keep only k bits
    int num = 0;
    // build first k-bit number
    for (int i = 0; i < k; i++) {
        num = (num << 1) | (s.charAt(i) - '0');
    }
    seen.add(num);
    // slide window through the rest of the string
    for (int i = k; i < n; i++) {
        num = ((num << 1) & mask) | (s.charAt(i) - '0');
        seen.add(num);
    }
    return seen.size() == total;
}

