public String getSmallestString(int n, int k) {
    // Validate input: smallest possible sum is n (all 'a'), largest is 26*n (all 'z')
    if (n <= 0 || k < n || k > 26 * n) {
        return null; // or throw new IllegalArgumentException("Invalid input");
    }
    StringBuilder sb = new StringBuilder(n);
    // Initialize with 'a's
    for (int i = 0; i < n; i++) {
        sb.append('a');
    }
    int remaining = k - n; // how much we need to add to reach k
    // Distribute the remaining value from the end to maintain lexicographic minimality
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each char can increase by at most 25 ('a'->'z')
        sb.setCharAt(i, (char) ('a' + add));
        remaining -= add;
    }
    return sb.toString();
}

