public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    for (int d = 0; d <= m + n - 2; d++) {
        int startRow = Math.max(0, d - n + 1);
        int endRow = Math.min(m - 1, d);
        if (d % 2 == 0) {
            // even diagonal: iterate from endRow to startRow
            for (int i = endRow; i >= startRow; i--) {
                int j = d - i;
                result[index++] = mat[i][j];
            }
        } else {
            // odd diagonal: iterate from startRow to endRow
            for (int i = startRow; i <= endRow; i++) {
                int j = d - i;
                result[index++] = mat[i][j];
            }
        }
    }
    return result;
}

